(()=>{const studies={limestone:{title:'The Limestone Retreat',image:'assets/natural-bathroom.png',alt:'Naturally lit limestone bathroom with an oak vanity',description:'A warm, minimal direction built around daylight, pale stone and the texture of oak. A circular frameless mirror and considered fittings keep the room calm and open. This is an illustrative design study; completed project photos and client details have not been supplied.',materials:['Limestone','Oak','Polished chrome']},garden:{title:'The Garden Bath',image:'assets/natural-garden.png',alt:'Olive tiled bathroom with a garden outlook',description:'A nature-led bathroom direction pairing olive tile with walnut and soft terrazzo. The shower and vanity share a quiet material palette, with garden light doing the rest. This is an illustrative design study; completed project photos and client details have not been supplied.',materials:['Olive tile','Walnut','Brushed metal']}};document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=studies[button.dataset.project];const img=document.getElementById('project-modal-image');img.src=p.image;img.alt=p.alt;document.getElementById('project-modal-title').textContent=p.title;document.getElementById('project-modal-description').textContent=p.description;const list=document.getElementById('project-modal-materials');list.replaceChildren(...p.materials.map(text=>{const span=document.createElement('span');span.textContent=text;return span}));document.getElementById('projectmodal').showModal()}));if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.project-card,.hecuba-image,.hecuba-copy,.brand-grid,.cabin-intro,.crew-process article,.cabin-photo').forEach(el=>{el.classList.add('portfolio-reveal');observer.observe(el)})}})();
